def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([-7]), fmt([0]), fmt([5, 5]), fmt([1, 2, 3]), fmt([-4, 9]),
             fmt([10**9, -10**9, 10**9, -10**9, 10**9]), fmt([0, 0, 0, 0])]
    for n in (2, 3, 4, 5, 6, 8, 10, 15, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(-50, 50) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([10**9] * 100000))
    tests.append(fmt([(-10**9 if i % 2 else 10**9) for i in range(99999)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(77777)]))
    return tests
